/**
 * Collider event display — Scene3D runtime (Prompt 08, premium rendering).
 *
 * A barrel detector (tracker → ECAL → HCAL → muon system) around a synthetic
 * pp collision generated by js/science/collider-kinematics.mjs: seeded
 * four-vector kinematics, greedy cone jets, and missing transverse momentum.
 * Visible particles draw as curved tracks (charge-bent, η-stacked), energy
 * flows into an InstancedMesh calorimeter tower grid (24 φ × 12 η, |η| < 2.5),
 * jets get open cones, and MET gets a dashed arrow. Beam bunches stream in and
 * collide at t = THIT; reduced motion snaps to the fully-reconstructed state.
 *
 * THE EVENT IS A SYNTHETIC FIXTURE — never a CERN observation. The caller
 * labels this in-canvas and in the caption.
 */

import {
  AdditiveBlending, Color, ConeGeometry, CylinderGeometry, Group, InstancedBufferAttribute, InstancedMesh, Mesh, MeshBasicMaterial, Object3D,
  SphereGeometry, Sprite, SpriteMaterial, Vector3,
} from "three";
import { BufferAttributeNode, MeshBasicNodeMaterial } from "three/webgpu";
import { dot, positionLocal, uniform } from "three/tsl";
import { createDataPoints } from "../../render/materials/data-points.mjs";
import {
  syntheticEvent, eventSummary, clusterJets, pT, pseudorapidity, azimuth,
  COLLIDER_LAB_DEFAULTS, COLLIDER_CHANNELS,
} from "../../science/collider-kinematics.mjs";
import { seededRng } from "../../physics.mjs";
import { sharedGlowTexture } from "../glow-texture.mjs";
import * as TK from "../../design/tokens.mjs";

const R = 4.4;      // barrel radius
const LEN = 6.6;    // barrel half-length ×2
const THIT = 0.55;  // seconds until the beams collide
const TOWERS_PHI = 24;
const TOWERS_ETA = 12;
const ETA_MAX = 2.5;

// Token names, resolved when each line is built, so a theme change takes effect on the next build.
const TRACK_COLOR = {
  jet: "pigment-cyan-80-c09", bquark: "pigment-azure-74-c11", electron: "pigment-blue-72", positron: "pigment-blue-72",
  muon: "pigment-violet-72-c15", antimuon: "pigment-violet-72-c15", photon: "pigment-amber-79-c12", neutrino: "pigment-red-65",
};
const DASHED_KINDS = new Set(["photon", "neutrino"]);
const TRACK_DASH = { size: 0.18, gap: 0.12 };
const MET_DASH = { size: 0.2, gap: 0.14 };

export function createColliderDisplayRuntime({
  channel = COLLIDER_LAB_DEFAULTS.channel,
  sqrtSGev = COLLIDER_LAB_DEFAULTS.sqrtSGev,
  coneR = COLLIDER_LAB_DEFAULTS.coneR,
  seed = 1,
  camera = null, engraved,
} = {}) {
  if (!engraved) throw new TypeError("createColliderDisplayRuntime needs ctx.engraved (the scene's engraved line API)");
  if (!COLLIDER_CHANNELS.includes(channel)) {
    throw new TypeError(`unknown channel: ${channel}`);
  }
  const event = syntheticEvent({ channel, sqrtSGev, seed });
  const summary = eventSummary(event);
  const group = new Group();
  group.name = "collider-event-lab";
  const disposables = [];
  const track = (o) => { disposables.push(o); return o; };
  const trackLine = (line) => { track(line.geometry); track(line.material); if (line.userData.engraved.halo) trackLine(line.userData.engraved.halo); return line; };

  // ---- barrel detector: wireframe cylinders + beam axis ----
  const layers = [[0.55, "tracker"], [0.68, "ECAL"], [0.82, "HCAL"], [1.0, "muon system"]];
  for (const [fr] of layers) {
    const cyl = new Mesh(
      track(new CylinderGeometry(R * fr, R * fr, LEN, 30, 1, true)),
      track(new MeshBasicMaterial({
        color: TK.hex("ink-faint"), wireframe: true, transparent: true,
        opacity: fr === 1 ? 0.1 : 0.07, depthWrite: false,
      })),
    );
    cyl.rotation.x = Math.PI / 2;
    group.add(cyl);
  }
  {
    const axis = trackLine(engraved.line([0, 0, -LEN * 0.62, 0, 0, LEN * 0.62], {
      color: "ink-faint", opacity: 0.4, widthPx: engraved.WIDTH_PX.hairline, layer: "decoration",
    }));
    group.add(axis);
  }

  // ---- interaction vertex + beam bunches ----
  const vertex = new Mesh(track(new SphereGeometry(0.1, 16, 12)),
    track(new MeshBasicMaterial({ color: TK.hex("pigment-white") })));
  group.add(vertex);
  const vFlash = new Sprite(track(new SpriteMaterial({
    map: sharedGlowTexture(), color: TK.hex("pigment-amber-97"), transparent: true, opacity: 0.12,
    blending: AdditiveBlending, depthWrite: false,
  })));
  vFlash.scale.setScalar(1.2);
  group.add(vFlash);
  const BZ = LEN * 0.6;
  const beamMats = [];
  const beams = [1, -1].map(() => {
    const m = track(new SpriteMaterial({
      map: sharedGlowTexture(), color: TK.hex("pigment-azure-84"), transparent: true, opacity: 0,
      blending: AdditiveBlending, depthWrite: false,
    }));
    beamMats.push(m);
    const s = new Sprite(m);
    s.scale.setScalar(1.3);
    group.add(s);
    return s;
  });

  // ---- tracks: curved, η-stacked, charge-bent (schematic curvature) ----
  const NPT = 40;
  const visible = event.particles.filter((p) => p.visible);
  const trackLines = [];
  // The hardest visible track is the scene's focal curve (2.5 px); the others are 1.25 px.
  const hardest = visible.reduce((best, p, i) => (pT(p) > pT(visible[best]) ? i : best), 0);
  for (let idx = 0; idx < visible.length; idx++) {
    const p = visible[idx];
    const pt = Math.max(1e-3, pT(p));
    const phi = azimuth(p);
    const eta = pseudorapidity(p);
    const charge = p.charge || 0;
    const curve = charge * 0.55 / Math.max(1, pt / 12); // stronger bend for soft charged tracks
    const reach = Math.min(1, 0.35 + 0.65 * Math.log10(1 + pt) / Math.log10(1 + 400));
    const buf = new Float32Array((NPT + 1) * 3);
    for (let i = 0; i <= NPT; i++) {
      const f = i / NPT;
      const rr = f * reach * R;
      buf[i * 3] = Math.cos(phi + curve * f * 1.1) * rr;
      buf[i * 3 + 1] = Math.sin(phi + curve * f * 1.1) * rr;
      buf[i * 3 + 2] = eta * f * LEN * 0.42;
    }
    const line = trackLine(engraved.line(buf, {
      color: TRACK_COLOR[p.kind] || "pigment-blue-75-c05", opacity: 0.95, additive: true,
      widthPx: idx === hardest ? engraved.WIDTH_PX.focal : engraved.WIDTH_PX.standard,
      dash: DASHED_KINDS.has(p.kind) ? TRACK_DASH : null, layer: "model",
    }));
    engraved.setCount(line, 0);
    Object.assign(line.userData, { idx, kind: p.kind, info: `${p.kind} · pT ${pt.toFixed(1)} GeV · η ${eta.toFixed(2)} · φ ${phi.toFixed(2)}` });
    line.frustumCulled = false;
    group.add(line);
    trackLines.push({ line, points: NPT + 1 });
  }

  // ---- calorimeter towers: InstancedMesh φ24 × η12, ET-weighted ----
  const bins = new Float32Array(TOWERS_PHI * TOWERS_ETA);
  const binFill = (p, weight) => {
    const eta = pseudorapidity(p);
    if (!Number.isFinite(eta) || Math.abs(eta) >= ETA_MAX) return;
    const phi = azimuth(p);
    const ip = Math.floor(((phi + Math.PI) / (2 * Math.PI)) * TOWERS_PHI) % TOWERS_PHI;
    const ie = Math.floor(((eta + ETA_MAX) / (2 * ETA_MAX)) * TOWERS_ETA);
    bins[ie * TOWERS_PHI + ip] += weight;
  };
  for (const p of visible) {
    if (p.kind === "jet" || p.kind === "bquark") binFill(p, pT(p));
    else if (p.kind === "photon" || p.kind === "electron" || p.kind === "positron") binFill(p, pT(p));
  }
  const jets = clusterJets(event.particles, { coneR });
  for (const j of jets) {
    if (Math.abs(j.eta) < ETA_MAX) {
      const ip = Math.floor(((j.phi + Math.PI) / (2 * Math.PI)) * TOWERS_PHI) % TOWERS_PHI;
      const ie = Math.floor(((j.eta + ETA_MAX) / (2 * ETA_MAX)) * TOWERS_ETA);
      bins[ie * TOWERS_PHI + ip] += j.et * 0.5; // jet cores already carry member pT; add core weight
    }
  }
  const maxBin = Math.max(1e-6, ...bins);
  const towerGeo = track(new ConeGeometry(0.16, 1, 4)); // 4-sided pyramid towers
  // The towers rise with the tracks in the vertex stage (S08): the instance matrices hold the final towers and never change; each
  // vertex is scaled along its tower's axis, about the tower's base, by the `towerGrow` uniform. The CPU rewrote and re-uploaded
  // every tower matrix each frame of the 1.2 s rise.
  const towerGrow = uniform(1);
  const towerBases = new Float32Array(bins.length * 3), towerAxes = new Float32Array(bins.length * 3);
  const towerMat = track(new MeshBasicNodeMaterial({ transparent: true, opacity: 0.85, blending: AdditiveBlending, depthWrite: false, fog: false }));
  const baseNode = new BufferAttributeNode(new InstancedBufferAttribute(towerBases, 3), "vec3");
  const axisNode = new BufferAttributeNode(new InstancedBufferAttribute(towerAxes, 3), "vec3");
  {
    // positionLocal here is already instanced (NodeMaterial.setupPosition applies the instance matrix first)
    const offset = positionLocal.sub(baseNode);
    const along = dot(offset, axisNode);
    towerMat.positionNode = baseNode.add(offset.sub(axisNode.mul(along))).add(axisNode.mul(along.mul(towerGrow)));
    towerMat.userData.qgaNodeKit = true;
    towerMat.userData.kit = "collider-towers";
  }
  const towers = new InstancedMesh(towerGeo, towerMat, bins.length);
  towers.frustumCulled = false;
  const dummy = new Object3D();
  const coldC = new Color(TK.hex("pigment-blue-58")), hotC = new Color(TK.hex("pigment-orange-86"));
  const towerBase = new Float32Array(bins.length); // normalized height per tower
  for (let i = 0; i < bins.length; i++) {
    if (bins[i] <= 0) { towers.setColorAt(i, coldC); continue; }
    const f = bins[i] / maxBin;
    towerBase[i] = 0.12 + 1.15 * Math.sqrt(f);
    const ie = Math.floor(i / TOWERS_PHI);
    const ip = i % TOWERS_PHI;
    const phi = ((ip + 0.5) / TOWERS_PHI) * 2 * Math.PI - Math.PI;
    const eta = ((ie + 0.5) / TOWERS_ETA) * 2 * ETA_MAX - ETA_MAX;
    const rad = R * 0.86;
    dummy.position.set(Math.cos(phi) * rad, Math.sin(phi) * rad, eta * LEN * 0.19);
    dummy.rotation.set(0, 0, phi - Math.PI / 2);
    dummy.scale.set(1, towerBase[i], 1);
    dummy.updateMatrix();
    towers.setMatrixAt(i, dummy.matrix);
    towers.setColorAt(i, coldC.clone().lerp(hotC, Math.min(1, f * 1.4)));
    // base of the tower (the cone's bottom centre) and its outward axis, for the vertex-stage rise
    const ax = Math.cos(phi), ay = Math.sin(phi), half = towerBase[i] / 2;
    towerAxes[i * 3] = ax; towerAxes[i * 3 + 1] = ay;
    towerBases[i * 3] = dummy.position.x - ax * half; towerBases[i * 3 + 1] = dummy.position.y - ay * half; towerBases[i * 3 + 2] = dummy.position.z;
  }
  group.add(towers);

  // ---- jet cones: open wireframe cones along (φ, η) ----
  const jetCones = [];
  const up = new Vector3(0, 1, 0);
  for (const j of jets) {
    const dir = new Vector3(Math.cos(j.phi), Math.sin(j.phi), Math.sinh(j.eta)).normalize();
    const h = 2.3;
    const cone = new Mesh(
      track(new ConeGeometry(Math.tan(coneR) * h, h, 20, 1, true)),
      track(new MeshBasicMaterial({
        color: TK.hex("pigment-cyan-80-c09"), wireframe: true, transparent: true, opacity: 0.3,
        blending: AdditiveBlending, depthWrite: false,
      })),
    );
    cone.quaternion.setFromUnitVectors(up, dir);
    cone.position.copy(dir).multiplyScalar(h / 2);
    cone.userData = { info: `jet · ET ${j.et.toFixed(0)} GeV · η ${j.eta.toFixed(2)} · ${j.nMembers} objects` };
    group.add(cone);
    jetCones.push(cone);
  }

  // ---- MET arrow: dashed line + head along the missing-pT direction ----
  if (event.met.et > 1e-6) {
    const phi = event.met.phi;
    const len = Math.min(1, event.met.et / 300) * R * 0.9 + R * 0.25;
    const dir = new Vector3(Math.cos(phi), Math.sin(phi), 0);
    const line = trackLine(engraved.line([0, 0, 0, dir.x * len, dir.y * len, 0], {
      color: "pigment-red-65", opacity: 0.95, widthPx: engraved.WIDTH_PX.standard, dash: MET_DASH, layer: "model",
    }));
    Object.assign(line.userData, { info: `missing E_T · ${event.met.et.toFixed(0)} GeV · φ ${phi.toFixed(2)}` });
    group.add(line);
    const head = new Mesh(track(new ConeGeometry(0.14, 0.4, 10)),
      track(new MeshBasicMaterial({ color: TK.hex("pigment-red-65"), transparent: true, opacity: 0.95, depthWrite: false })));
    head.quaternion.setFromUnitVectors(up, dir);
    head.position.copy(dir).multiplyScalar(len + 0.2);
    group.add(head);
  }

  // ---- seeded ambient dust for depth ----
  {
    const rng = seededRng((seed >>> 0) + 7);
    const n = 160;
    const pos = new Float32Array(n * 3);
    for (let i = 0; i < n; i++) {
      const r = 6 + rng() * 14, th = rng() * Math.PI * 2, u = rng() * 2 - 1;
      const s = Math.sqrt(1 - u * u);
      pos[i * 3] = r * s * Math.cos(th); pos[i * 3 + 1] = r * u; pos[i * 3 + 2] = r * s * Math.sin(th);
    }
    // Points are one pixel on the node renderers: the dust is instanced sprites.
    const dust = createDataPoints({ positions: pos, color: TK.linear("pigment-blue-47"), sizePx: 0.3, sizeAttenuation: true, profile: "soft", additive: true, opacity: 0.4 });
    track(dust.material);
    dust.object.frustumCulled = false;
    group.add(dust.object);
  }

  function sync({ time = 0, motion = 1 } = {}) {
    // Reduced motion: snap to the fully-reconstructed event (post-collision).
    const t = motion === 0 ? THIT + 1.4 : (Number(time) || 0);
    const grow = Math.min(1, Math.max(0, (t - THIT) / 1.2));
    if (t < THIT) {
      const f = t / THIT, z = BZ * (1 - f * f);
      beams[0].position.set(0, 0, z);
      beams[1].position.set(0, 0, -z);
      const flicker = 0.55 + 0.45 * Math.abs(Math.sin(t * 34));
      beamMats[0].opacity = beamMats[1].opacity = flicker;
      const sc = 1.1 + 0.5 * Math.sin(t * 30);
      beams[0].scale.setScalar(sc); beams[1].scale.setScalar(sc);
    } else {
      beamMats[0].opacity = beamMats[1].opacity = 0;
    }
    const burst = t < THIT ? 0 : Math.exp(-(t - THIT) * 2.4);
    vFlash.scale.setScalar(1.2 + 5.5 * burst);
    vFlash.material.opacity = 0.12 + 0.75 * burst;
    const drawn = Math.max(2, Math.floor(grow * (NPT + 1)));
    for (const tl of trackLines) engraved.setCount(tl.line, drawn);
    towerGrow.value = grow;
  }

  function dispose() {
    for (const d of disposables) d.dispose?.();
    towers.dispose?.();
    group.removeFromParent?.();
  }

  return {
    mesh: group,
    kind: "collider-event",
    pickables: trackLines.map((tl) => tl.line),
    stats: () => ({
      kind: "collider-event",
      channel,
      particles: visible.length,
      jets: summary.nJets,
      metGev: summary.metEt,
      masses: summary.masses,
      fixture: true,
    }),
    sync,
    dispose,
    recoverable: () => false,
  };
}